// Synthetic LCD observations, fake single-field commands and unshown WPF only.
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
using RogControl;

public static class LcdSettingsGuiTests {
 static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Static;
 static int checks,layouts;
 static void Check(bool good,string label){checks++;if(!good)throw new Exception(label);}
 static void Near(double value,double expected,string label){Check(Math.Abs(value-expected)<0.01,label+" actual="+value+" expected="+expected);}
 static Dictionary<string,object> Map(params object[] items){var map=new Dictionary<string,object>();for(int i=0;i<items.Length;i+=2)map.Add((string)items[i],items[i+1]);return map;}
 static Dictionary<string,object> Fixture(){return Map("deviceId","7299","readbackConfirmed",true,"deviceAlive",true,"placeholder",false,"supportsWrite",true,"supportedSettings",new[]{"powerS0","powerS5","brightness","standby","presetId"},"brightness",null,"brightnessReadable",false,"brightnessWritable",true,"brightnessMin",10,"brightnessMax",100,"brightnessStep",10,"standbyEnabled",null,"standbyReadable",false,"standbyWritable",true,"powerS5",false,"firmware","AB12");}
 static object Call(MainWindow window,string name,params object[] args){return typeof(MainWindow).GetMethod(name,Hidden).Invoke(window,args);}
 static bool Supports(Dictionary<string,object> state,string setting){return (bool)Call(null,"LcdSettingsSupports",state,setting);}
 static IEnumerable<T> Logical<T>(DependencyObject root)where T:DependencyObject{if(root is T)yield return (T)root;foreach(object child in LogicalTreeHelper.GetChildren(root)){var item=child as DependencyObject;if(item==null)continue;foreach(T match in Logical<T>(item))yield return match;}}
 static T Tagged<T>(DependencyObject root,string tag)where T:FrameworkElement{return Logical<T>(root).Single(item=>Object.Equals(item.Tag,tag));}
 static object Field(MainWindow window,string name){return typeof(MainWindow).GetField(name,Hidden).GetValue(window);}
 static void Set(MainWindow window,string name,object value){typeof(MainWindow).GetField(name,Hidden).SetValue(window,value);}
 static FrameworkElement Build(MainWindow window,Dictionary<string,object> state,Func<string,bool> mayApply,Action<string,Dictionary<string,object>> apply,Action cancel){return (FrameworkElement)Call(window,"BuildLcdSettingsBody",state,mayApply,apply,cancel,false);}
 static void Pump(FrameworkElement root){root.UpdateLayout();Dispatcher.CurrentDispatcher.Invoke(new Action(()=>{}),DispatcherPriority.Background);root.UpdateLayout();}
 static void Layout(FrameworkElement root,double width,double height){root.Measure(new Size(width,height));root.Arrange(new Rect(0,0,width,height));Pump(root);}
 static void Click(Button button){button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
 static void NoNative(MainWindow window){Check(!window.IsVisible&&PresentationSource.FromVisual(window)==null,"no owner HWND or shown window");Check(((Dictionary<string,WorkerClient>)Field(window,"sdkWorkers")).Count==0,"no SDK worker or hardware query");Check(!((WorkerClient)Field(window,"gearWorker")).Running,"no peripheral worker");}

 static void Facts(MainWindow window){
  var good=Fixture();foreach(string setting in new[]{"powerS5","brightness","standby"})Check(Supports(good,setting),"existing exact capability: "+setting);
  foreach(string setting in new[]{"powerS0","presetId","temperatureWarning","wallpaper","save",""})Check(!Supports(good,setting),"settings popup does not gain an unimplemented command: "+setting);
  Check(!Supports(null,"brightness"),"missing observation is not writable");
  foreach(string flag in new[]{"readbackConfirmed","deviceAlive","supportsWrite"})foreach(object invalid in new object[]{null,false,"true",1}){var state=Fixture();state[flag]=invalid;foreach(string setting in new[]{"powerS5","brightness","standby"})Check(!Supports(state,setting),"strict observation/write flag: "+flag);}
  foreach(object invalid in new object[]{null,true,"false",0}){var state=Fixture();state["placeholder"]=invalid;Check(!Supports(state,"powerS5"),"placeholder must be confirmed false");}
  foreach(object invalid in new object[]{null,"",7299,"7299 ","7300"}){var state=Fixture();state["deviceId"]=invalid;Check(!Supports(state,"powerS5"),"exact LCD identity only");}
  foreach(string cap in new[]{"brightnessWritable","standbyWritable"})foreach(object invalid in new object[]{null,false,"true",1}){var state=Fixture();state[cap]=invalid;Check(!Supports(state,cap=="brightnessWritable"?"brightness":"standby"),"per-field write capability is strict");}
  foreach(string field in new[]{"brightnessMin","brightnessMax","brightnessStep"})foreach(object invalid in new object[]{null,"10",10.0,true,-1,0,101}){var state=Fixture();state[field]=invalid;Check(!Supports(state,"brightness")&&!Supports(state,"standby"),"unsupported or non-integral brightness range rejected");Check(Supports(state,"powerS5"),"brightness range does not remove independent power capability");}
  foreach(object invalid in new object[]{null,"brightness",new[]{"Brightness"},new object[]{1,true},new string[0]}){var state=Fixture();state["supportedSettings"]=invalid;Check(!Supports(state,"brightness"),"explicit supported-setting membership required");}
  foreach(string invalid in new[]{null,"","0000","AB1","AB123","ZZZZ","AB12 "}){var state=Fixture();state["firmware"]=invalid;Check((string)Call(null,"LcdSettingsFirmware",state)=="—","unknown firmware is not inherited from the reference image");}
  Check((string)Call(null,"LcdSettingsFirmware",good)=="AB12","confirmed firmware remains exact");
  var snapshots=(Dictionary<string,Dictionary<string,object>>)Field(window,"sdkSnapshots");snapshots["lcd:7299"]=good;((HardwareControlPolicy)Field(window,"hardwareControlPolicy")).SetEnabled(true);Check(!(bool)Call(window,"LcdSettingsMayApply",good,"brightness"),"render-only always blocks real command");Set(window,"render",false);
  Check((bool)Call(window,"LcdSettingsMayApply",good,"brightness"),"current confirmed session and explicit consent permit one existing field");
  foreach(string flag in new[]{"busy","closing"}){Set(window,flag,true);Check(!(bool)Call(window,"LcdSettingsMayApply",good,"brightness"),"lifecycle blocks command: "+flag);Call(window,"OpenLcdSettings");Set(window,flag,false);}
  snapshots["lcd:7299"]=Fixture();Check(!(bool)Call(window,"LcdSettingsMayApply",good,"brightness"),"same device in a replacement observation rejects old popup callbacks");snapshots.Clear();Check(!(bool)Call(window,"LcdSettingsMayApply",good,"brightness"),"disconnected session rejects popup callback");((HardwareControlPolicy)Field(window,"hardwareControlPolicy")).SetEnabled(false);Set(window,"render",true);Call(window,"OpenLcdSettings");NoNative(window);
 }
 static void Commands(MainWindow window){
  var state=Fixture();bool enabled=true;var sent=new List<KeyValuePair<string,Dictionary<string,object>>>();int cancelled=0;var root=Build(window,state,setting=>enabled&&Supports(state,setting),(setting,args)=>sent.Add(new KeyValuePair<string,Dictionary<string,object>>(setting,args)),()=>cancelled++);Layout(root,485,677);
  var extra=Tagged<Expander>(root,"LcdSettings.Additional");extra.IsExpanded=true;Pump(root);var levels=Tagged<ComboBox>(root,"LcdSettings.ManualBrightness");var bright=Tagged<Button>(root,"LcdSettings.ApplyBrightness");var power=Tagged<Button>(root,"LcdSettings.ApplyS5");var standby=Tagged<Button>(root,"LcdSettings.ApplyStandby");var s5=Tagged<CheckBox>(root,"LcdSettings.ManualS5");var dim=Tagged<CheckBox>(root,"LcdSettings.ManualStandby");
  Check(levels.SelectedIndex==0&&!bright.IsEnabled&&!standby.IsEnabled,"no fabricated brightness draft on open");Check(s5.IsChecked==false&&power.IsEnabled,"confirmed OFF is preserved for independent S5 control");Check(dim.IsChecked==null,"unreadable standby is indeterminate");
  Click(bright);Click(standby);Check(sent.Count==0,"missing draft values emit no command even through raised events");
  foreach(string level in new[]{"10","50","100"}){levels.SelectedItem=level;Click(bright);Check(sent.Last().Key=="brightness"&&sent.Last().Value.Count==1&&(int)sent.Last().Value["value"]==Int32.Parse(level),"manual brightness emits one existing single-field request");}
  foreach(bool value in new[]{true,false}){s5.IsChecked=value;Click(power);Check(sent.Last().Key=="powerS5"&&sent.Last().Value.Count==1&&(bool)sent.Last().Value["value"]==value,"power request preserves explicit true/false");dim.IsChecked=value;Click(standby);Check(sent.Last().Key=="standby"&&sent.Last().Value.Count==2&&(bool)sent.Last().Value["enabled"]==value&&(int)sent.Last().Value["brightness"]==100,"standby keeps its required enabled and brightness fields");}
  int before=sent.Count;enabled=false;Click(bright);Click(power);Click(standby);Check(sent.Count==before,"late busy/disconnect/capability gate is checked at callback time");enabled=true;s5.IsChecked=null;dim.IsChecked=null;levels.SelectedItem="请选择亮度";Click(bright);Click(power);Click(standby);Check(sent.Count==before,"returning to unknown choices cannot write null or default values");
  Click(Tagged<Button>(root,"LcdSettings.Save"));Check(sent.Count==before&&cancelled==0,"disabled Save cannot imply an aggregate submit or close");Click(Tagged<Button>(root,"LcdSettings.Cancel"));Check(cancelled==1&&sent.Count==before,"Cancel only closes, without applying drafts");NoNative(window);
 }
 static void CheckLayout(MainWindow window,Dictionary<string,object> state,int width,int height,string name,string output){
  int sent=0,cancelled=0;var root=Build(window,state,setting=>false,(setting,args)=>sent++,()=>cancelled++);((Control)root).FontFamily=window.FontFamily;Layout(root,width,height);
  var surface=Tagged<Grid>(root,"LcdSettings.Surface");var frame=Tagged<Border>(root,"LcdSettings.Frame");Near(frame.ActualWidth,485,"original physical canvas width");Near(frame.ActualHeight,677,"original physical canvas height");Near(surface.ActualWidth,483,"one-pixel popup borders accounted for");Near(surface.ActualHeight,675,"content does not overflow fixed popup height");
  var brightness=Tagged<Slider>(root,"LcdSettings.Brightness");bool known=state!=null&&(bool)Call(null,"LcdSettingsObserved",state)&&Object.Equals(state["brightnessReadable"],true)&&state["brightness"] is int&&(int)state["brightness"]>=10&&(int)state["brightness"]<=100;
  Check(Tagged<TextBlock>(root,"LcdSettings.BrightnessValue").Text==(known?state["brightness"]+"%":"—"),"brightness display follows confirmed getter, not saved defaults");brightness.ApplyTemplate();var track=(Track)brightness.Template.FindName("PART_Track",brightness);Check(track.Visibility==(known?Visibility.Visible:Visibility.Collapsed),"unknown brightness has no fake 10 percent thumb or progress");Check(!brightness.IsEnabled&&brightness.TickFrequency==10,"main slider remains a truthful readout, manual write is separate");
  var temperature=Tagged<Slider>(root,"LcdSettings.Temperature");temperature.ApplyTemplate();Check(((Track)temperature.Template.FindName("PART_Track",temperature)).Visibility==Visibility.Collapsed&&!temperature.IsEnabled,"temperature has no invented 80 degree threshold");Check(Tagged<TextBlock>(root,"LcdSettings.TemperatureValue").Text=="—","temperature state stays unknown");
  for(int i=0;i<6;i++)Check(Tagged<TextBlock>(root,"LcdSettings.TemperatureTick."+i).Text==(75+i*5)+" °C","six official temperature labels retain their order");
  Check(!Tagged<Border>(root,"LcdSettings.TemperatureAlert").IsEnabled&&!Tagged<Border>(root,"LcdSettings.SleepPower").IsEnabled,"unknown alert and combined sleep/hibernate/S5 switch cannot write");Check(Logical<TextBlock>(Tagged<Border>(root,"LcdSettings.SleepPower")).Single().Text=="—","S5 alone never masquerades as combined sleep and hibernate state");
  for(int i=0;i<2;i++){var wallpaper=Tagged<Border>(root,"LcdSettings.Wallpaper."+i);Check(!wallpaper.IsEnabled&&wallpaper.Child==null&&wallpaper.Width==64&&wallpaper.Height==112,"preset slot has original portrait proportions and no asset read in pure build");}
  Check(!Tagged<Button>(root,"LcdSettings.Save").IsEnabled&&Tagged<Button>(root,"LcdSettings.Cancel").IsEnabled,"unsupported Save disabled, Cancel usable without hardware permission");Check(Tagged<TextBlock>(root,"LcdSettings.Firmware").Text=="当前版本：  "+(string)Call(null,"LcdSettingsFirmware",state),"firmware readout remains observed or unknown");
  foreach(var block in Logical<TextBlock>(surface)){if(block.ActualWidth<=0||block.ActualHeight<=0)continue;Check(block.TextTrimming!=TextTrimming.None||block.DesiredSize.Width-block.Margin.Left-block.Margin.Right<=block.ActualWidth+1,"text has no intrinsic horizontal clipping: "+block.Text);var bounds=block.TransformToAncestor(surface).TransformBounds(new Rect(0,0,block.ActualWidth,block.ActualHeight));Check(bounds.Left>=-1&&bounds.Right<=surface.Width+1,"text fits original modal canvas: "+block.Text);}
  if(output!=null)Save(root,width,height,output,name+"-"+width+".png");
  var extra=Tagged<Expander>(root,"LcdSettings.Additional");extra.IsExpanded=true;Pump(root);var viewport=Tagged<ScrollViewer>(root,"LcdSettings.Viewport");viewport.ScrollToBottom();Pump(root);var standby=Tagged<Button>(root,"LcdSettings.ApplyStandby");var commandBounds=standby.TransformToAncestor(viewport).TransformBounds(new Rect(0,0,standby.ActualWidth,standby.ActualHeight));Check(commandBounds.Bottom<=viewport.ActualHeight+1&&commandBounds.Top>=0,"retained standby controls reachable through inner scrolling");
  var outer=Tagged<ScrollViewer>(root,"LcdSettings.FrameViewport");outer.ScrollToBottom();outer.ScrollToRightEnd();Pump(root);var cancel=Tagged<Button>(root,"LcdSettings.Cancel");var cancelBounds=cancel.TransformToAncestor(root).TransformBounds(new Rect(0,0,cancel.ActualWidth,cancel.ActualHeight));Check(cancelBounds.Right<=width+1&&cancelBounds.Bottom<=height+1&&cancelBounds.Left>=0,"Cancel remains reachable in narrow work areas");
  foreach(var button in Logical<Button>(surface))Click(button);Check(sent==0&&cancelled==1,"render build has no write path and exactly one Cancel callback");NoNative(window);layouts++;
 }
 static void Dpi(MainWindow window){
  foreach(double dpi in new[]{1.0,1.25,1.5,2.0}){object[] args={new Size(1920/dpi,1080/dpi),dpi,dpi,new Size()};Check((bool)Call(null,"TryLcdSettingsDialogBounds",args),"normal owned-popup DPI accepted");var bounds=(Size)args[3];Near(bounds.Width*dpi,485,"owned popup physical width remains 485");Near(bounds.Height*dpi,677,"owned popup physical height remains 677");var root=Build(window,null,setting=>false,(setting,data)=>{throw new Exception("DPI render cannot submit");},()=>{});root.LayoutTransform=new ScaleTransform(1/dpi,1/dpi);var container=new Grid();container.Children.Add(root);Layout(container,bounds.Width,bounds.Height);var frame=Tagged<Border>(root,"LcdSettings.Frame");var physical=frame.TransformToAncestor(container).TransformBounds(new Rect(0,0,frame.ActualWidth,frame.ActualHeight));Near(physical.Width*dpi,485,"own inverse content transform preserves frame width");Near(physical.Height*dpi,677,"own inverse content transform preserves frame height");layouts++;}
  foreach(double invalid in new[]{0.0,-1.0,Double.NaN,Double.PositiveInfinity,0.49,8.01}){object[] args={new Size(1000,1000),invalid,invalid,new Size()};Check(!(bool)Call(null,"TryLcdSettingsDialogBounds",args),"invalid popup scale rejected");}
  object[] narrow={new Size(350,540),1.0,1.0,new Size()};Check((bool)Call(null,"TryLcdSettingsDialogBounds",narrow),"small work area allowed with local popup scrolling");var small=(Size)narrow[3];Near(small.Width,334,"small work area width retains margin");Near(small.Height,524,"small work area height retains margin");NoNative(window);
 }
 static void Save(FrameworkElement root,int width,int height,string output,string name){var image=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);image.Render(root);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using(var stream=File.Create(Path.Combine(output,name)))encoder.Save(stream);}
 [STAThread] public static int Main(string[] args){try{Run(args);return 0;}catch(Exception error){for(Exception current=error;current!=null;current=current.InnerException)Console.Error.WriteLine(current.GetType().Name+": "+current.Message+"\n"+current.StackTrace);return 1;}}
 static void Run(string[] args){new Application();string output=args.Length==2&&args[0]=="--render"?Path.GetFullPath(args[1]):null;if(output!=null)Directory.CreateDirectory(output);var window=new MainWindow(true);Facts(window);Commands(window);var known=Fixture();known["brightnessReadable"]=true;known["brightness"]=30;var unknown=Fixture();var noDevice=Fixture();noDevice["deviceAlive"]=false;var wrongType=Fixture();wrongType["brightnessReadable"]=true;wrongType["brightness"]="30";var wrongId=Fixture();wrongId["deviceId"]="7300";var fixtures=new[]{known,unknown,noDevice,wrongType,wrongId,null};for(int index=0;index<fixtures.Length;index++)foreach(int width in new[]{485,300})CheckLayout(window,fixtures[index],width,width==485?677:520,"fixture-"+index,output);Dpi(window);Console.WriteLine("LCD settings: "+checks+" checks, "+layouts+" unshown layouts; no HWND, hardware reads or writes.");}
}
